import os
import torch


class Config:
    # -------------------------------------------------------------------------
    # Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the analysis step
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Cache directory for processed graphs and scalers
    CACHE_DIR = "./working/idea_6"
    os.makedirs(CACHE_DIR, exist_ok=True)

    # Checkpoint paths
    CHECKPOINT_DIR = os.path.join(CACHE_DIR, "checkpoints")
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")

    # Submission path
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data Processing & Graph Construction
    # -------------------------------------------------------------------------
    # Cutoff radius for neighbor search in Angstroms
    CUTOFF_RADIUS = 5.0

    # Maximum number of neighbors to consider (for efficiency/tensor sizing)
    MAX_NEIGHBORS = 12

    # Global features to extract:
    # 3 Lattice Lengths + 3 Lattice Angles + 4 Atomic Fractions (Al, Ga, In, O)
    N_GLOBAL_FEATURES = 10

    # Target columns in the CSV
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]

    # -------------------------------------------------------------------------
    # Model Architecture (VN-CGCNN)
    # -------------------------------------------------------------------------
    # Dimension of atom (node) embeddings (based on atomic number)
    ATOM_EMBEDDING_DIM = 64

    # Number of Gaussian RBF basis functions for edge expansion
    N_RBF = 60

    # Hidden dimension for internal update vectors
    HIDDEN_DIM = 64

    # Number of interaction blocks (Atom <-> Virtual Node <-> Atom)
    N_CONV_LAYERS = 4

    # Dropout probability for regularization
    DROPOUT = 0.1

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    # Random seed for reproducibility
    SEED = 42

    # Batch size (set to 48 as per strategy)
    BATCH_SIZE = 48

    # Learning rate
    LEARNING_RATE = 1e-3

    # Weight decay for AdamW optimizer
    WEIGHT_DECAY = 1e-4

    # Training duration and early stopping
    NUM_EPOCHS = 150
    PATIENCE = 15  # Stop if validation loss doesn't improve for 15 epochs

    # -------------------------------------------------------------------------
    # Hardware
    # -------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # For DataLoader
